{
  "findings": [
    {
      "check_id": "CKV_GCP_10",
      "title": "Legacy ABAC enabled on GKE cluster",
      "resource": "google_container_cluster.k8sexample",
      "severity": "HIGH",
      "explanation": "Enabling `enable_legacy_abac` allows Attribute-Based Access Control, which is deprecated and less secure than RBAC. It should be disabled to enforce proper role-based access controls."
    },
    {
      "check_id": "CKV_GCP_11",
      "title": "Kubernetes Alpha features enabled",
      "resource": "google_container_cluster.k8sexample",
      "severity": "MEDIUM",
      "explanation": "Setting `enable_kubernetes_alpha` to true enables alpha features that are not supported by Google Cloud and may contain security vulnerabilities or instability. This should be disabled for production environments."
    },
    {
      "check_id": "CKV_GCP_29",
      "title": "Basic Authentication (username/password) enabled",
      "resource": "google_container_cluster.k8sexample",
      "severity": "CRITICAL",
      "explanation": "Using `master_auth` with username and password is insecure and deprecated. Basic authentication should be disabled in favor of service account tokens or OIDC integration."
    }
  ],
  "patched_code": "resource \"google_container_cluster\" \"k8sexample\" {\n  name               = \"${var.vault_user}-k8s-cluster\"\n  description        = \"example k8s cluster\"\n  zone               = \"${var.gcp_zone}\"\n  initial_node_count = \"${var.initial_node_count}\"\n  enable_kubernetes_alpha = \"false\"\n  enable_legacy_abac = \"false\"\n  master_auth {\n    username = \"\"\n    password = \"\"\n    client_certificate_config {\n      issue_client_certificate = false\n    }\n  }\n  node_config {\n    machine_type = \"${var.node_machine_type}\"\n    disk_size_gb = \"${var.node_disk_size}\"\n    oauth_scopes = [\n      \"https://www.googleapis.com/auth/compute\",\n      \"https://www.googleapis.com/auth/devstorage.read_only\",\n      \"https://www.googleapis.com/auth/logging.write\",\n      \"https://www.googleapis.com/auth/monitoring\"\n    ]\n  }\n}",
  "fix_summary": "Disabled legacy ABAC and Kubernetes alpha features to reduce attack surface and ensure stability. Removed basic authentication credentials from the master_auth block by setting username and password to empty strings and disabling client certificate issuance, enforcing more secure authentication methods."
}
